export type Offer = 'sale' | 'clearance' | 'new';

// The offers as the merchandising sheet exports them (its spelling of the offer varies).
const SHEET = 'p1:Sale p3:Clearance p4:New p6:sale p7:clearance';

export const OFFERS: Record<string, string> = Object.fromEntries(SHEET.split(' ').map(entry => entry.split(':')).map(([id, offer]) => [id, offer]));

export const OFFER_COLORS: Record<Offer, string> = { sale: '#d1242f', clearance: '#f0883e', new: '#2da44e' };
export const NO_OFFER = '#c8c8c8';

export function markColor(id: string): string {
  return OFFER_COLORS[OFFERS[id] as Offer] ?? NO_OFFER;
}
import React, { useEffect, useState } from 'react';
import { FlatList, Text } from 'react-native';
import { getProducts, getStock, type Product } from '../api';
import type { ScreenProps } from '../routes';
import { ProductRow } from './ProductRow';

export function Products({ navigation }: ScreenProps<'Products'>) {
  const [items, setItems] = useState<Product[] | null>(null);
  const [stock, setStock] = useState<Record<string, number>>({});
  useEffect(() => {
    getProducts().then(r => setItems(r.body));
    getStock().then(r => setStock(r.body));
  }, []);
  if (!items) return <Text style={{ padding: 16 }}>Loading…</Text>;
  return (
    <FlatList
      testID="products/list"
      data={items}
      keyExtractor={p => p.id}
      renderItem={({ item }) => <ProductRow item={item} stock={stock[item.id] ?? 0} onPress={() => navigation.navigate('Product', { id: item.id })} />}
    />
  );
}
import React from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import type { Product } from '../api';
import { formatPrice } from '../price';
import { RowMark } from './RowMark';

export function ProductRow({ item, stock, onPress }: { item: Product; stock?: number; onPress: () => void }) {
  return (
    <Pressable testID={`row/${item.id}`} onPress={onPress} style={styles.row}>
      <View style={styles.left}>
        <RowMark id={item.id} />
        <Text style={styles.name}>{item.name}</Text>
      </View>
      {stock !== undefined ? <Text testID={`row/${item.id}/stock`}>{stock > 0 ? 'In stock' : 'Out of stock'}</Text> : null}
      <Text testID={`row/${item.id}/price`}>{formatPrice(item.price)}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: 'row', justifyContent: 'space-between', padding: 16, borderBottomWidth: StyleSheet.hairlineWidth, borderColor: '#ccc' },
  left: { flexDirection: 'row' },
  name: { fontSize: 16 },
});
